S = "Hakeem Force Academy"
QS = [
(S, "Which prophet (AS) was given the skill of working with iron, which Allah made soft for him?", ["Hazrat Sulaiman (AS)", "Hazrat Dawood (AS)", "Hazrat Yaqub (AS)", "Hazrat Idris (AS)"], 1, "The Quran (Surah Saba) says Allah made iron soft for Hazrat Dawood (AS), so he could make armour and coats of mail.", "Hazrat Dawood (AS) was also given the Zabur.", [4939]),
(S, "Monrovia is the capital city of which country?", ["Liberia", "Sierra Leone", "Ghana", "Nigeria"], 0, "Monrovia is the capital and largest city of Liberia in West Africa.", "Monrovia is named after the US President James Monroe.", [783, 3226]),
(S, "Which are the first and the last months of the Islamic (Hijri) calendar?", ["Rabi ul Awwal and Shaban", "Muharram and Dhul Hijjah", "Ramadan and Shawwal", "Muharram and Dhul Qadah"], 1, "The Hijri year begins with Muharram and ends with Dhul Hijjah (Zil Hajj), the month of Hajj.", "The Hijri calendar starts from the migration of the Prophet (PBUH) to Madina in 622 AD.", [2846]),
(S, "How many months are there in the Islamic (Hijri) year?", ["10", "11", "12", "13"], 2, "The Islamic year has 12 lunar months, as stated in the Quran (Surah At-Tawbah).", "Four of these months (Muharram, Rajab, Dhul Qadah, Dhul Hijjah) are sacred months.", [510]),
(S, "What was the main feature of the Minto-Morley Reforms of 1909?", ["Introduction of separate electorates for Muslims", "Partition of Bengal", "Abolition of the Viceroy's Council", "Complete provincial autonomy"], 0, "The Indian Councils Act 1909 (Minto-Morley Reforms) gave Muslims the right to elect their own representatives through separate electorates.", "The reforms are named after Lord Minto (Viceroy) and John Morley (Secretary of State for India).", [3980]),
(S, "Choose the correct word: When morning ___, the murderer was caught.", ["reached", "arrived", "came", "went"], 2, "The natural phrase is 'when morning came', meaning when daylight arrived.", "'Arrive' and 'reach' usually need a place or destination, while 'come' suits time and seasons.", [649, 4069]),
(S, "Moroni is the capital city of which country?", ["Comoros", "Madagascar", "Mauritius", "Seychelles"], 0, "Moroni is the capital of the Union of the Comoros, an island country in the Indian Ocean.", "It lies on Grande Comore island, near the coast of East Africa.", [80, 3218]),
(S, "The Faisal Mosque in Islamabad was designed by which architect?", ["Vedat Dalokay", "Nadeem Mirza", "Ahmed Ali Khan", "Sinan Pasha"], 0, "The Faisal Mosque was designed by the Turkish architect Vedat Dalokay and its design is inspired by a Bedouin tent.", "It was funded by the Saudi king Faisal bin Abdulaziz and is named after him.", [4783]),
(S, "What is the motto of the Pakistan Army?", ["Faith, Unity, Discipline", "Iman, Taqwa, Jihad fi Sabilillah", "Unity, Faith, Order", "Duty, Honour, Country"], 1, "The motto of the Pakistan Army is Iman, Taqwa, Jihad fi Sabilillah (Faith, Piety, Struggle in the way of Allah).", "Faith, Unity, Discipline is the motto given by Quaid-e-Azam to the nation.", [3630]),
(S, "In which country is Mount Olympus, the highest mountain in its range and home of the gods in myth, located?", ["Italy", "Turkey", "Greece", "Egypt"], 2, "Mount Olympus is located in northern Greece and is its highest mountain.", "In Greek mythology it was the home of the twelve Olympian gods.", [2207]),
(S, "Who was the first Pakistani mountaineer to climb Mount Everest?", ["Hassan Sadpara", "Nazir Sabir", "Ashraf Aman", "Samina Baig"], 1, "Nazir Sabir reached the summit of Mount Everest in 2000, becoming the first Pakistani to do so.", "Ashraf Aman was the first Pakistani to climb K2, in 1977.", [5119]),
(S, "The Karakoram mountain range lies on the border of Pakistan and which country?", ["India", "Afghanistan", "China", "Iran"], 2, "The Karakoram range lies in northern Pakistan along the border with China (and also touches India).", "The Karakoram Highway connects Pakistan and China through the Khunjerab Pass.", [2727]),
(S, "Table Mountain, a famous flat-topped mountain, is located near which city?", ["Cape Town", "Nairobi", "Cairo", "Lagos"], 0, "Table Mountain overlooks the city of Cape Town in South Africa.", "It is one of the New7Wonders of Nature.", [4126]),
(S, "What was the Faraizi Movement?", ["A religious reform movement among the Muslims of Bengal", "A political party of the Hindus", "A military uprising in Punjab", "A trade union movement"], 0, "The Faraizi Movement was started in Bengal by Haji Shariatullah to make Muslims follow the faraiz (obligations) of Islam and give up un-Islamic customs.", "After Haji Shariatullah the movement was led by his son Dudu Miyan.", [3899]),
(S, "The speed of a train is twice that of a car. If the car moves at 60 km/h, what is the speed of the train?", ["90 km/h", "100 km/h", "120 km/h", "180 km/h"], 2, "Train speed = 2 x 60 = 120 km/h.", "At 120 km/h the train covers 2 km every minute.", [621, 437]),
(S, "Ali walks 10 km north, then turns left and then turns right. Which direction is he facing now?", ["North", "South", "East", "West"], 0, "Facing north, a left turn makes him face west; a right turn from west brings him back to face north.", "A left turn followed by a right turn cancels out.", [1473]),
(S, "Which was the first James Bond film?", ["Goldfinger", "From Russia with Love", "Dr. No", "Thunderball"], 2, "Dr. No, released in 1962 with Sean Connery, was the first James Bond film.", "James Bond was created by the writer Ian Fleming.", [1305]),
(S, "Hazrat Muaz bin Jabal (RA) was appointed as governor of which place?", ["Yemen", "Bahrain", "Syria", "Egypt"], 0, "The Prophet (PBUH) sent Hazrat Muaz bin Jabal (RA) to Yemen as governor and teacher.", "He was well known as the most knowledgeable Companion about halal and haram.", [1748, 1749]),
(S, "What is 4x multiplied by 4x, plus 2x multiplied by 4x?", ["20x", "24x squared", "16x squared", "32x squared"], 1, "4x times 4x = 16 x squared, and 2x times 4x = 8 x squared. Their sum is 24 x squared.", "When multiplying terms, the coefficients are multiplied and the powers of x are added.", [2969]),
(S, "Fill in the blank: The man was charged ___ murder.", ["of", "with", "for", "by"], 1, "The correct phrase is 'charged with' a crime.", "'Accused of' is also correct, but 'charged' takes the preposition 'with'.", [1664]),
(S, "Why did Allah send Hazrat Musa (AS) to Pharaoh (Firaun)?", ["To trade with him", "To invite him to Allah and demand freedom for Bani Israel", "To teach him writing", "To fight a war against him"], 1, "Hazrat Musa (AS) was sent to call Pharaoh to worship one Allah and to free Bani Israel from slavery.", "His brother Hazrat Harun (AS) was sent with him to help.", [5255]),
(S, "According to Greek mythology, who flew too close to the sun with wings of wax and fell into the sea?", ["Daedalus", "Icarus", "Perseus", "Hercules"], 1, "Icarus ignored his father's warning, flew too close to the sun, the wax melted and he fell.", "His father Daedalus built the wings and the labyrinth of Crete.", [623]),
(S, "To which place did the Prophet (PBUH) migrate in 622 AD (13 Nabawi)?", ["Taif", "Madina", "Abyssinia", "Jerusalem"], 1, "In 622 AD the Prophet (PBUH) migrated from Makkah to Madina (then called Yathrib).", "This migration (Hijrat) is the start of the Hijri calendar.", [2790]),
(S, "What gift did Allah give to the Prophet (PBUH) during the Miraj?", ["Zakat", "Five daily prayers", "Fasting in Ramadan", "The Hajj"], 1, "During the Miraj the five daily prayers (Salah) were made obligatory for Muslims.", "Salah is the only pillar of Islam that was given directly in the heavens.", [3856]),
]
